// Preparar parámetros de búsqueda para el scraper Playwright/LinkedIn
// NOTA: URLSearchParams no está disponible en el sandbox de n8n; usamos encodeURIComponent manual
const input = $json ?? {};
const isWebhook = ['query', 'body', 'headers', 'params'].some(k => Object.prototype.hasOwnProperty.call(input, k));
const incoming = input.query && typeof input.query === 'object'
  ? input.query
  : (input.body && typeof input.body === 'object' ? input.body : input);

if (isWebhook && incoming.source && String(incoming.source).trim().toLowerCase() !== 'linkedin') {
  throw new Error('El webhook sólo acepta source=linkedin');
}

const textParam = v => Array.isArray(v)
  ? v.map(String).map(s => s.trim()).filter(Boolean).join(',')
  : String(v ?? '').trim();

const boundedInt = (v, name, min, max) => {
  if (v === undefined || v === null || v === '') return null;
  const n = Number(v);
  if (!Number.isInteger(n) || n < min || n > max) throw new Error(`${name} debe ser entero entre ${min} y ${max}`);
  return String(n);
};

// Parámetros por defecto alineados con config.js del scraper
const location = textParam(incoming.location) || 'Barcelona Metropolitan Area';
const keywords = textParam(incoming.keywords) ||
  'Industrial Engineer,Supply Chain,Project Manager,Business Analyst,Operations,Digital Transformation,Aerospace,Automation,Strategy,Consultant';

const requestTimeout = 180000;
const baseUrl = String($env.PLAYWRIGHT_BASE_URL || 'http://playwright:3000').replace(/\/+$/, '');

// Construcción manual de query string (encodeURIComponent sí está disponible en el sandbox)
const qp = [
  'location=' + encodeURIComponent(location),
  'keywords=' + encodeURIComponent(keywords),
];
const optionals = [
  ['termsPerQuery', boundedInt(incoming.termsPerQuery, 'termsPerQuery', 1, 20)],
  ['maxJobsPerSearch', boundedInt(incoming.maxJobsPerSearch, 'maxJobsPerSearch', 1, 200)],
  ['maxScrollSteps', boundedInt(incoming.maxScrollSteps, 'maxScrollSteps', 0, 20)],
  ['gotoTimeout', boundedInt(incoming.gotoTimeout, 'gotoTimeout', 1000, 120000)],
  ['selectorTimeout', boundedInt(incoming.selectorTimeout, 'selectorTimeout', 1000, 60000)],
];
for (const [name, value] of optionals) {
  if (value !== null) qp.push(encodeURIComponent(name) + '=' + encodeURIComponent(value));
}

return [{ json: {
  source: 'linkedin',
  targetUrl: baseUrl + '/linkedin?' + qp.join('&'),
  requestTimeout,
  requestedAt: new Date().toISOString(),
}}];

// Normalizar datos del scraper Playwright.
// El scraper devuelve un array de ofertas o un objeto con campo 'jobs'/'data'.
// Aplica la misma lógica de normalización que normalize.js del scraper.
const t = v => String(v ?? '').replace(/\s+/g, ' ').trim();
const cleanTitle = v => {
  const s = t(v); const h = s.length / 2;
  return Number.isInteger(h) && s.slice(0, h) === s.slice(h) ? s.slice(0, h).trim() : s;
};
const normalizeLink = v => {
  const raw = t(v); if (!raw) return null;
  try {
    const url = new URL(raw, 'https://www.linkedin.com');
    url.hostname = url.hostname.toLowerCase().replace(/^www\./, '');
    url.search = ''; url.hash = '';
    url.pathname = url.pathname.replace(/\/+$/, '') || '/';
    return url.href;
  } catch { return raw; }
};
const extractId = link => link?.match(/(?:-|%2D|\/view\/)(\d+)(?:[/?]|$)/i)?.[1] || null;
const ARRAY_FIELDS = ['skills', 'requirements', 'education', 'languages', 'experience', 'detectedKeywords'];
const expand = v => {
  if (Array.isArray(v)) return v;
  if (v && Array.isArray(v.body)) return expand(v.body);
  if (v && Array.isArray(v.jobs)) return v.jobs;
  if (v && Array.isArray(v.data)) return v.data;
  return v && typeof v === 'object' ? [v] : [];
};

const now = new Date().toISOString();
const output = [];
const inputs = $input.all();
const prepared = $('Preparar solicitudes Playwright').all();

for (let i = 0; i < inputs.length; i++) {
  const item = inputs[i];
  const response = item.json;
  // Detectar error del scraper
  const errMsg = item.error?.message || response?.error?.message || (typeof response?.error === 'string' ? response.error : null);
  if (errMsg) {
    output.push({ json: {
      __playwrightError: true, source: 'linkedin', error_message: t(errMsg),
      item_key: '', title: '', payload_json: JSON.stringify({ source: 'linkedin', error_message: t(errMsg) })
    }});
    continue;
  }
  const jobs = expand(response);
  let produced = 0;
  for (const raw of jobs) {
    if (!raw || typeof raw !== 'object') continue;
    if (raw.source && String(raw.source).toLowerCase() !== 'linkedin') continue;
    const link = normalizeLink(raw.link);
    const title = cleanTitle(raw.title);
    if (!title) continue;
    const id = t(raw.id) || extractId(link);
    const company = t(raw.company) || null;
    const location = t(raw.location) || null;
    const fallback = [company, title, location].map(t).join('|').toLocaleLowerCase();
    const identity = link ? `url:${link}` : (id ? `id:${id}` : `fallback:${fallback}`);
    const job = {
      ...raw, id: id || null, title, company, location, link,
      source: 'linkedin', scrapedAt: raw.scrapedAt || now,
      item_key: `job:linkedin:${identity}`,
    };
    for (const f of ARRAY_FIELDS) job[f] = Array.isArray(job[f]) ? [...new Set(job[f].map(t).filter(Boolean))] : [];
    // Campo de texto para filtrado y scoring
    job.fullText = t([title, raw.description, raw.summary, job.skills.join(' '), job.requirements.join(' ')].filter(Boolean).join(' '));
    job.payload_json = JSON.stringify({ ...job });
    output.push({ json: job });
    produced++;
  }
  if (!produced) {
    output.push({ json: {
      __playwrightEmpty: true, source: 'linkedin', error_message: 'No se encontraron ofertas',
      item_key: '', title: '', payload_json: JSON.stringify({ source: 'linkedin', jobs: [] })
    }});
  }
}
return output;

// Filtrar ofertas irrelevantes antes de la deduplicación.
// Basado en las listas INCLUDE/EXCLUDE de playwright/config.js + criterios de nivel y ubicación.

const ROLES_INCLUDE = [
  'project manager', 'program manager', 'pmo', 'business analyst', 'operations',
  'process improvement', 'continuous improvement', 'lean', 'operational excellence',
  'industrial engineer', 'industrial engineering', 'supply chain', 'logistics',
  'digital transformation', 'innovation', 'consultant', 'consulting', 'strategy',
  'business intelligence', 'data analyst', 'product manager', 'product owner',
  'planning', 'manufacturing', 'automation', 'technology', 'aerospace',
  'aeronautical', 'aeroespacial', 'aeronautica', 'espacio', 'space',
  'inteligencia artificial', 'artificial intelligence', 'project engineer',
  'program management', 'transformation', 'change management', 'industrialization',
  'performance', 'production planning', 's&op', 'planning engineer',
  'business process', 'industrial performance', 'ingeniería industrial',
  'ingeniería de organización', 'engineer', 'engineering', 'associate',
  'graduate', 'junior', 'trainee', 'entry level', 'young talent',
];

const ROLES_EXCLUDE = [
  'mecánico', 'mechanical engineer', 'electrical engineer', 'electrónico',
  'electronics engineer', 'embedded', 'firmware', 'climatización', 'hvac',
  'electromecánico', 'robotics engineer', 'validation engineer', 'qa engineer',
  'electrical design', 'mechanical design', 'cad engineer', 'plc', 'scada',
  'instrumentación', 'civil engineer', 'obras', 'peritaje', 'patente',
  'mantenimiento', 'ferroviario', 'head of', 'chief', 'vp ', 'vice president',
  'director', 'sales engineer', 'account manager', 'sales manager',
  'marketing manager', 'retail', 'hospitality', 'freelance',
];

// Niveles a excluir (experiencia elevada)
const LEVEL_EXCLUDE = [
  /\bsenior\b/i, /\bsr\.?\b/i, /\blead\b/i, /\bprincipal\b/i, /\bstaff\b/i,
  /\bhead of\b/i, /\bdirector\b/i, /\bmanaging director\b/i,
];

// Ubicaciones aceptadas (si hay info de location)
const LOCATION_OK = [
  'barcelona', 'madrid', 'spain', 'españa', 'remote', 'hybrid', 'remoto',
  'híbrido', 'hibrid', 'spain', 'cataluña', 'catalunya', 'catalonia',
  'valencia', 'bilbao', 'sevilla', 'zaragoza', 'malaga'
];

const includes = (text, terms) => terms.some(t => text.includes(t.toLowerCase()));
const matchesAny = (text, patterns) => patterns.some(p => p.test(text));

const output = [];
for (const item of $input.all()) {
  const job = item.json;
  // Pasar errores/vacíos sin filtrar
  if (job.__playwrightError || job.__playwrightEmpty) { output.push(item); continue; }
  if (!job.title) continue;

  const titleLow = (job.title || '').toLowerCase();
  const fullLow = (job.fullText || job.title || '').toLowerCase();

  // 1. Debe pasar el filtro de inclusión (título o texto completo)
  if (!includes(titleLow, ROLES_INCLUDE) && !includes(fullLow, ROLES_INCLUDE)) continue;

  // 2. No debe contener términos excluidos en el TÍTULO
  if (includes(titleLow, ROLES_EXCLUDE)) continue;

  // 3. Excluir niveles senior/director por título
  if (matchesAny(titleLow, LEVEL_EXCLUDE)) {
    // Permitir si también contiene junior/graduate/trainee (p.ej. "Senior Project para Junior")
    const hasJunior = /\b(junior|graduate|trainee|intern|entry.level|young)\b/i.test(titleLow);
    if (!hasJunior) continue;
  }

  // 4. Filtro de ubicación: si hay location y no coincide con ninguna aceptada, descartar
  if (job.location) {
    const locLow = job.location.toLowerCase();
    if (!LOCATION_OK.some(l => locLow.includes(l))) continue;
  }

  output.push(item);
}
return output.length ? output : [{ json: {
  __noResults: true, source: 'linkedin', title: '', item_key: '',
  payload_json: JSON.stringify({ source: 'linkedin', message: 'Sin ofertas tras filtrado' })
}}];

// Extraer solo las ofertas NUEVAS (inserted=true) y calcular scoring determinista.
// Empresas prioritarias del proyecto (conservadas de la configuración existente).

const PRIORITY_COMPANIES = [
  'airbus', 'boeing', 'indra', 'thales', 'leonardo', 'safran', 'gmv', 'sener',
  'esa', 'nasa', 'spacex', 'arianespace', 'deimos', 'elecnor', 'altran', 'capgemini',
  'accenture', 'mckinsey', 'bcg', 'bain', 'deloitte', 'pwc', 'kpmg', 'ey',
  'siemens', 'general electric', 'honeywell', 'collins aerospace', 'raytheon',
  'northrop grumman', 'lockheed martin', 'dassault', 'rolls royce', 'pratt whitney',
  'ge aviation', 'mtorres', 'aernnova', 'alestis', 'aciturri', 'cesa', 'iberia',
  'vueling', 'aena', 'enaire', 'boeing españa', 'airbus spain', 'aer lingus',
  'seat', 'volkswagen', 'tesla', 'bmw', 'mercedes', 'caterpillar', 'volvo',
  'amazon', 'google', 'microsoft', 'apple', 'meta', 'ibm', 'oracle', 'sap',
  'palantir', 'salesforce', 'workday', 'servicenow', 'splunk', 'datadog',
];

const ROLE_SCORES = {
  aerospace: 30, aeroespacial: 30, aeronautical: 30, 'espacio': 25,
  'artificial intelligence': 25, 'inteligencia artificial': 25, automation: 22,
  'digital transformation': 20, transformacion: 18, 'supply chain': 18,
  operations: 15, 'project manager': 18, 'project engineer': 18,
  'program manager': 16, 'business analyst': 15, consultant: 14, strategy: 14,
  manufacturing: 13, 'industrial engineer': 18, 'ingeniería industrial': 18,
  planning: 12, logistics: 12, lean: 12, 'continuous improvement': 12,
  technology: 10, engineering: 10, engineer: 8,
};

const LEVEL_BONUS = {
  intern: 10, internship: 10, trainee: 10, graduate: 15, junior: 15,
  'entry level': 12, 'young talent': 14, associate: 10,
};

const LOCATION_BONUS = {
  barcelona: 20, madrid: 18, spain: 15, españa: 15, remote: 12, hybrid: 10,
  remoto: 12, híbrido: 10, cataluña: 14, catalunya: 14,
};

const t = v => String(v ?? '').replace(/\s+/g, ' ').trim();

function computeScore(payload) {
  let score = 0;
  const title = (payload.title || '').toLowerCase();
  const full = (payload.fullText || payload.description || payload.title || '').toLowerCase();
  const company = (payload.company || '').toLowerCase();
  const location = (payload.location || '').toLowerCase();
  const modality = (payload.remote === true || /remoto|remote/i.test(full)) ? 'remote' :
                   (payload.hybrid === true || /h[ií]brido|hybrid/i.test(full)) ? 'hybrid' : 'presencial';

  // Scoring por rol (busca en título primero, luego en texto)
  for (const [term, pts] of Object.entries(ROLE_SCORES)) {
    if (title.includes(term)) { score += pts; break; }
  }
  // Bonus menor si el rol aparece solo en texto completo
  for (const [term, pts] of Object.entries(ROLE_SCORES)) {
    if (!title.includes(term) && full.includes(term)) { score += Math.floor(pts * 0.4); break; }
  }

  // Nivel profesional
  for (const [level, pts] of Object.entries(LEVEL_BONUS)) {
    if (title.includes(level) || full.includes(level)) { score += pts; break; }
  }

  // Ubicación
  for (const [loc, pts] of Object.entries(LOCATION_BONUS)) {
    if (location.includes(loc)) { score += pts; break; }
  }
  // Modalidad
  if (modality === 'remote') score += 8;
  else if (modality === 'hybrid') score += 5;

  // Empresa prioritaria
  for (const co of PRIORITY_COMPANIES) {
    if (company.includes(co)) { score += 20; break; }
  }

  // Salario (si existe)
  if (payload.salary && String(payload.salary).trim()) {
    const match = String(payload.salary).match(/(\d[\d.,]+)/);
    if (match) {
      const sal = parseFloat(match[1].replace(',', '.').replace('.', ''));
      if (sal > 40000) score += 15;
      else if (sal > 30000) score += 10;
      else if (sal > 20000) score += 5;
    } else {
      score += 5; // tiene info salarial aunque no parseable
    }
  }

  return Math.min(score, 100);
}

const jobs = $input.all()
  .filter(item =>
    item.json.inserted === true &&
    item.json.is_control !== true &&
    item.json.source === 'linkedin'
  )
  .map(item => {
    const payload = item.json.payload && typeof item.json.payload === 'object'
      ? item.json.payload : {};
    const job = {
      ...payload,
      item_key: item.json.item_key || payload.item_key,
      score: computeScore(payload),
    };
    return { json: job };
  });

return jobs;

// Seleccionar las 3 mejores ofertas por puntuación.
// Umbral mínimo: 20 puntos para que la oferta se considere relevante.
const MIN_SCORE = 20;
const MAX_OFFERS = 3;

const all = $input.all().map(i => i.json);

const top = all
  .filter(job => (job.score || 0) >= MIN_SCORE)
  .sort((a, b) => (b.score || 0) - (a.score || 0))
  .slice(0, MAX_OFFERS);

if (top.length === 0) {
  return [{ json: { __noTopOffers: true, totalScored: all.length } }];
}

return top.map(job => ({ json: job }));

