// Validar respuesta de Gemini y fusionar con los datos de la oferta.
// Si Gemini falla, usamos fallback con la descripción original.
let geminiData = null;
try {
  const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text ?? null;
  if (raw) {
    const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
    if (parsed && typeof parsed.resumen === 'string' && parsed.resumen.trim()) {
      geminiData = parsed;
    }
  }
} catch (e) {
  // Gemini devolvió algo no parseable: usamos fallback
}

// Recuperar la oferta original del nodo TOP 3
// (la referencia se mantiene en el item porque n8n pasa el item a cada nodo)
const original = $('Seleccionar TOP 3').item.json;

const resumen = geminiData?.resumen ||
  (original.fullText || original.description || '').substring(0, 200) ||
  'Sin descripción disponible.';

return [{ json: {
  ...original,
  resumen,
  motivo_fit: geminiData?.motivo_fit || '',
}}];

// Construir el mensaje de Telegram para una oferta.
// Formato HTML compatible con Telegram.
const job = $json;

const escapeHtml = s => String(s || '').replace(/&/g,'&').replace(/</g,'<').replace(/>/g,'>');

const titulo = escapeHtml(job.title || 'Sin título');
const empresa = escapeHtml(job.company || 'Empresa desconocida');
const ubicacion = escapeHtml(job.location || 'Ubicación no especificada');
const score = job.score || 0;
const resumen = escapeHtml((job.resumen || '').substring(0, 300));
const enlace = job.link || '';

let msg = '';
msg += `💼 <b>${titulo}</b>\n\n`;
msg += `🏢 <b>Empresa:</b> ${empresa}\n`;
msg += `📍 <b>Ubicación:</b> ${ubicacion}\n`;
msg += `⭐ <b>Puntuación:</b> ${score}/100\n\n`;
if (resumen) msg += `📝 <b>Resumen:</b>\n${resumen}\n\n`;
if (enlace) msg += `🔗 <a href="${enlace}">Ver oferta en LinkedIn</a>\n`;
msg += '────────────────────';

return [{ json: { ...job, telegramMessage: msg } }];

// Rama de control: manejar casos sin ofertas o errores del scraper
// Este nodo recibe los items is_control=true o __noTopOffers de los nodos anteriores
const inputs = $input.all();

// Caso: no hay ofertas TOP
const noTop = inputs.some(i => i.json.__noTopOffers === true);
if (noTop) {
  return [{ json: { type: 'no_offers', message: 'No se han encontrado nuevas ofertas relevantes hoy.' } }];
}

// Caso: error del scraper
const errors = inputs.filter(i => i.json.__playwrightError === true);
if (errors.length > 0) {
  const msgs = errors.map(e => e.json.error_message || 'Error desconocido').join(', ');
  return [{ json: { type: 'scraper_error', message: `Error en el scraper: ${msgs}` } }];
}

// Caso genérico
return [{ json: { type: 'no_results', message: 'No hay resultados que notificar.' } }];
